<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue'
defineProps<{ refined?: boolean }>()
const page = ref('overview'), query = ref(''), filter = ref('全部'), modal = ref<HTMLDialogElement>(), mode = ref(''), step = ref(1)
const names: Record<string,string> = {overview:'工作台',quotes:'客户报价',products:'产品资料',customers:'客户与品牌',pricing:'价格规则'}
const paths: Record<string,string> = {overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',products:'m12 3 9 5-9 5-9-5 9-5z M3 8v9l9 5 9-5V8 M12 13v9',quotes:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h5',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',pricing:'M4 4h7l10 10-7 7L4 11V4z M8 8h.01'}
const quotes = ref([
{no:'QT-20261102-006',customer:'华盛商贸有限公司',brand:'毅诺',type:'自有品牌',date:'2026-11-02',count:3,status:'待确认'},
{no:'QT-20261102-005',customer:'云禾生活用品有限公司',brand:'云禾',type:'客户贴牌',date:'2026-11-02',count:2,status:'草稿'},
{no:'QT-20261030-004',customer:'远辰供应链有限公司',brand:'毅诺',type:'自有品牌',date:'2026-10-30',count:5,status:'已确认'},
{no:'QT-20261029-003',customer:'华盛商贸有限公司',brand:'毅诺',type:'自有品牌',date:'2026-10-29',count:2,status:'待确认'},
{no:'QT-20261028-002',customer:'云禾生活用品有限公司',brand:'云禾',type:'客户贴牌',date:'2026-10-28',count:4,status:'已确认'}])
const products = [{sku:'YN-1001',name:'简约保温杯',spec:'500ml · 米白',kind:'产品',price:'32.00',unit:'个'}, {sku:'YN-1002',name:'便携随行杯',spec:'350ml · 松绿',kind:'产品',price:'26.50',unit:'个'}, {sku:'YN-2001',name:'替换杯盖',spec:'通用款 · 米白',kind:'配件',price:'5.00',unit:'个'}, {sku:'YN-3001',name:'双杯礼盒套装',spec:'500ml × 2 · 礼盒装',kind:'组合商品',price:'—',unit:'套'}]
const customers = ['华盛商贸有限公司','云禾生活用品有限公司','远辰供应链有限公司']
const filtered = computed(()=>quotes.value.filter(q=>(filter.value==='全部'||q.status===filter.value) && `${q.no}${q.customer}${q.brand}`.includes(query.value)))
const matchedProducts = computed(()=>products.filter(p=>(filter.value==='全部'||p.kind===filter.value)&&`${p.sku}${p.name}${p.spec}`.includes(query.value)))
const pending = computed(()=>quotes.value.filter(q=>q.status==='待确认').length)
watch(page,()=>{query.value='';filter.value='全部'})
const selected = ref(quotes.value[0]!), confirmed = ref<number[]>([])
const form = ref({customer:'',brand:'毅诺',type:'自有品牌',terms:'付款方式：款到发货。交货时间以订单确认为准。',date:'2026-11-02',expiry:'2026-11-16'})
const lines = ref([{sku:'YN-1001',quantity:500,price:'38.00'}])
const error = ref(''), toast = ref('')
function notify(text:string){toast.value=text;setTimeout(()=>toast.value='',3200)}
function open(kind:string){mode.value=kind;step.value=1;error.value='';if(kind==='create') {form.value.customer='';lines.value=[{sku:'YN-1001',quantity:500,price:'38.00'}]} modal.value?.showModal()}
function review(q:typeof selected.value){selected.value=q;confirmed.value=[];open('review')}
function advance(){error.value='';if(step.value===1&&!form.value.customer){error.value='请选择报价客户';return}if(step.value===2&&lines.value.some(l=>!Number.isInteger(l.quantity)||l.quantity<1||!l.price||Number(l.price)<=0)){error.value='请为每行填写正整数数量和大于 0 的固定单价';return}step.value++}
function generate(){quotes.value.unshift({no:'QT-20261102-007',customer:form.value.customer,brand:form.value.brand,type:form.value.type,date:form.value.date,count:new Set(lines.value.map(l=>l.sku)).size,status:'草稿'});modal.value?.close();page.value='quotes';notify('报价草稿已生成')}
function submit(){selected.value.status='待确认';modal.value?.close();notify('已提交，等待负责人确认')}
function confirmProduct(i:number){confirmed.value.push(i);if(confirmed.value.length===selected.value.count){selected.value.status='已确认';notify('所有产品已确认，可导出报价')}}
function selectType(){form.value.brand=form.value.type==='自有品牌'?'毅诺':'云禾'}
async function showPending(){page.value='quotes';await nextTick();filter.value='待确认'}
</script>

<template>
<div class="shell">
<aside class="sidebar"><div class="brand"><div class="logo">Y<span></span></div><div><strong>毅诺 <b>PLM</b></strong><small>产品与报价管理</small></div></div><div class="workspace"><span class="workspace-icon">毅</span><div>毅诺业务工作区<small>企业内部协作</small></div></div><p class="nav-label">业务管理</p><nav aria-label="主导航"><button v-for="(label,id) in names" :key="id" :class="{active:page===id}" :aria-current="page===id?'page':undefined" @click="page=String(id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="paths[id]"/></svg>{{label}}<span v-if="id==='quotes'" class="count">{{pending}}</span></button></nav><div class="side-foot"><span class="avatar">管</span><div>管理员<small>全部业务权限</small></div></div></aside>
<div class="main"><header><span>业务管理 <span class="slash">/</span> <b>{{names[page]}}</b></span><span class="header-right"><span class="connection"></span><span>内网工作区</span><span class="divider"></span><span class="header-date">2026年11月2日 · 周一</span></span></header>
<main>
<div class="page-heading"><div><p class="eyebrow">{{page==='overview'?'WORKSPACE':'PRODUCT & QUOTATION'}}</p><h1>{{page==='overview'?'把每一份报价，做到心中有数。':names[page]}}</h1><p class="subtitle">{{({overview:'从待办开始，让产品、价格与客户之间的协作更顺畅。',quotes:'查找、核对与跟进客户报价，确认后再对外发送。',products:'统一维护产品、配件与组合商品，按规格管理价格。',customers:'客户档案与品牌归属放在一起，报价时准确选择。',pricing:'按品牌、客户和商品规格维护数量阶梯。'} as Record<string,string>)[page]}}</p></div><button class="primary" @click="open('create')"><span class="plus">＋</span> 新建报价</button></div>
<template v-if="page==='overview'">
<div class="stats"><article><span>在售商品</span><strong>4<small>款</small></strong><span class="stat-note">产品、配件及组合商品</span></article><article><span>合作客户</span><strong>3<small>家</small></strong><span class="stat-note">客户档案统一管理</span></article><article class="attention"><span>待确认报价 <i></i></span><strong>{{pending}}<small>份</small></strong><button @click="showPending">去处理 <span aria-hidden="true">{{ refined ? '→' : '↗' }}</span></button></article><article><span>累计报价</span><strong>{{quotes.length}}<small>份</small></strong><span class="stat-note">保留各版本报价记录</span></article></div>
<div class="work-grid"><section class="panel todo"><div class="section-heading"><h2>今天先处理这些</h2><span class="small-label">报价待办</span></div><div class="task-highlight"><span class="task-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="paths.quotes"/></svg></span><div><h3>{{pending}} 份报价等待确认</h3><p>逐个产品核对所有数量档，再导出对外报价。</p></div><button class="outline" @click="showPending">查看待确认 <span>→</span></button></div><div class="task-bottom"><span>需要调整已确认报价？</span><span>复制为新版本，保留原始记录。</span></div></section><section class="panel shortcuts"><div class="section-heading"><h2>常用入口</h2></div><button @click="page='products'"><span>产品资料</span><small><template v-if="refined"><span class="phrase">商品资料</span><span class="phrase">规格与组成</span></template><template v-else>查商品、规格与组成</template></small><b aria-hidden="true">{{ refined ? '→' : '↗' }}</b></button><button @click="page='pricing'"><span>价格规则</span><small><template v-if="refined"><span class="phrase">维护品牌</span><span class="phrase">阶梯价格</span></template><template v-else>维护品牌阶梯价格</template></small><b aria-hidden="true">{{ refined ? '→' : '↗' }}</b></button><button @click="page='customers'"><span>客户与品牌</span><small><template v-if="refined"><span class="phrase">客户档案</span><span class="phrase">品牌归属</span></template><template v-else>管理客户及品牌归属</template></small><b aria-hidden="true">{{ refined ? '→' : '↗' }}</b></button></section></div>
</template>
<section v-if="page==='overview'||page==='quotes'" class="panel quote-panel"><div class="section-heading"><div class="heading-inline"><h2>{{page==='overview'?'最近报价':'报价单'}}</h2><span class="small-label">{{quotes.length}} 份</span></div><button v-if="page==='overview'" class="text-button" @click="page='quotes'">查看全部 <span>→</span></button></div><div class="table-toolbar"><div class="tabs" aria-label="报价状态"><button v-for="s in ['全部','草稿','待确认','已确认']" :class="{selected:filter===s}" :aria-pressed="filter===s" @click="filter=s">{{s}}<span v-if="s==='待确认'">{{pending}}</span></button></div><label class="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><input v-model="query" aria-label="搜索报价" placeholder="搜索报价单号、客户或品牌"></label></div><p v-if="refined" class="table-scroll-hint">左右滑动表格，查看状态与操作 →</p><div class="table-scroll" :tabindex="refined ? 0 : undefined" :aria-label="refined ? '业务数据表格，可左右滚动' : undefined"><table><thead><tr><th>报价单号 / 日期</th><th>客户 / 品牌</th><th>报价类型</th><th class="numeric">产品数</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="q in filtered" :key="q.no"><td><strong class="mono">{{q.no}}</strong><small>{{q.date}}</small></td><td><strong>{{q.customer}}</strong><small>{{q.brand}}</small></td><td>{{q.type}}</td><td class="numeric">{{q.count}} 款</td><td><span class="badge" :class="q.status==='待确认'?'amber':q.status==='已确认'?'green':'gray'"><i></i>{{q.status}}</span></td><td class="right"><button class="text-button" @click="review(q)">{{q.status==='待确认'?'核对报价':'查看详情'}} <span>→</span></button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">没有找到报价，请调整搜索词或状态筛选。</td></tr></tbody></table></div><div class="table-footer"><span>共 {{filtered.length}} 份报价</span><span>已确认报价保留价格快照</span></div></section>
<section v-if="page==='products'" class="panel"><div class="table-toolbar"><div class="tabs"><button v-for="s in ['全部','产品','配件','组合商品']" :class="{selected:filter===s}" @click="filter=s">{{s}}</button></div><label class="search"><input v-model="query" aria-label="搜索商品" placeholder="搜索货号、名称或规格"></label></div><div class="table-scroll" :tabindex="refined ? 0 : undefined" :aria-label="refined ? '业务数据表格，可左右滚动' : undefined"><table><thead><tr><th>商品 / 货号</th><th>规格</th><th>类型</th><th>单位</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="p in matchedProducts" :key="p.sku"><td><div class="product-cell"><span class="product-pic"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="paths.products"/></svg></span><div><strong>{{p.name}}</strong><small class="mono">{{p.sku}}</small></div></div></td><td>{{p.spec}}</td><td>{{p.kind}}</td><td>{{p.unit}}</td><td><span class="badge green"><i></i>在售</span></td><td class="right"><button class="text-button" @click="open('product:'+p.sku)">查看资料 →</button></td></tr><tr v-if="!matchedProducts.length"><td colspan="6" class="empty">未找到匹配商品</td></tr></tbody></table></div><div class="table-footer">共 {{matchedProducts.length}} 款商品</div></section>
<section v-if="page==='customers'" class="panel"><div class="section-heading"><h2>客户档案</h2><span class="small-label">3 家合作客户</span></div><div class="customer-row" v-for="(c,i) in customers"><span class="avatar">{{c[0]}}</span><div><h3>{{c}}</h3><p>{{i===1?'贴牌品牌：云禾':'自有品牌合作客户'}}</p></div><span class="badge green"><i></i>合作中</span><button class="text-button" @click="form.customer=c;open('create');form.customer=c">为客户报价 →</button></div></section>
<section v-if="page==='pricing'" class="panel"><div class="section-heading"><h2>毅诺 · 简约保温杯</h2><span class="badge gray">自有品牌</span></div><div class="pricing-description"><strong>YN-1001 · 500ml · 米白</strong><p>整批计价 · 按订购总数量匹配一个档位，全部数量使用该档单价。</p></div><div class="table-scroll" :tabindex="refined ? 0 : undefined" :aria-label="refined ? '业务数据表格，可左右滚动' : undefined"><table><thead><tr><th>订购数量</th><th>计价方式</th><th class="numeric">供货单价</th></tr></thead><tbody><tr v-for="t in [['1–499 个','42.00'],['500–999 个','38.00'],['1,000 个及以上','35.00']]"><td>{{t[0]}}</td><td>固定单价</td><td class="numeric">¥ {{t[1]}}</td></tr></tbody></table></div><div class="table-footer">规则用于新报价计算，历史报价保持生成时的价格。</div></section>
<footer class="page-footer"><span>毅诺 PLM</span><span>产品有据 · 价格有序 · 报价可追溯</span></footer>
</main></div></div>
<dialog ref="modal" :class="{wide:mode==='create',drawer:mode==='review'}" @close="error=''">
<div class="dialog-head"><div><p class="eyebrow">{{mode==='create'?'NEW QUOTATION':mode==='review'?'QUOTATION DETAIL':'PRODUCT DETAIL'}}</p><h2>{{mode==='create'?'新建客户报价':mode==='review'?selected.no:'商品资料'}}</h2></div><button class="close" aria-label="关闭" @click="modal?.close()">×</button></div>
<template v-if="mode==='create'"><div class="steps"><span v-for="(s,i) in ['客户与品牌','商品与数量档','商务条款']" :class="{current:step===i+1,done:step>i+1}"><b>{{i+1}}</b>{{s}}</span></div><div class="dialog-body"><template v-if="step===1"><h3>这份报价提供给谁？</h3><p class="muted">报价类型决定可选择的品牌和对外报价格式。</p><div class="form-grid"><label>报价类型<select v-model="form.type" @change="selectType"><option>自有品牌</option><option>客户贴牌</option></select></label><label>客户 <em>*</em><select v-model="form.customer"><option disabled value="">选择报价客户</option><option v-for="c in customers">{{c}}</option></select></label><label>品牌<select v-model="form.brand"><option>{{form.type==='自有品牌'?'毅诺':'云禾'}}</option></select></label><label>报价日期<input type="date" v-model="form.date"></label></div></template><template v-if="step===2"><h3>商品与数量档</h3><p class="muted">当前采用本次固定价格；同一商品可添加多行，分别设置数量档。</p><div v-for="(line,i) in lines" class="line-editor"><label>商品规格<select v-model="line.sku"><option v-for="p in products" :value="p.sku">{{p.name}} · {{p.spec}}</option></select></label><label>订购数量<input type="number" min="1" step="1" v-model.number="line.quantity"></label><label>固定单价（元）<input type="number" min="0.01" step="0.01" v-model="line.price"></label><button aria-label="移除数量档" class="close" :disabled="lines.length===1" @click="lines.splice(i,1)">×</button></div><button class="outline" @click="lines.push({sku:lines[0]!.sku,quantity:1000,price:'35.00'})">＋ 添加商品 / 数量档</button></template><template v-if="step===3"><h3>最后核对一下</h3><div class="summary-strip"><strong>{{form.customer}}</strong><span>{{form.type}} · {{form.brand}} · {{lines.length}} 个数量档</span></div><label>报价有效期至<input type="date" v-model="form.expiry" :min="form.date"></label><label>商务条款<textarea rows="4" v-model="form.terms"></textarea></label><p class="info">生成后先保留为草稿，提交确认并逐项核对后再导出。</p></template><p v-if="error" role="alert" class="error">{{error}}</p></div><div class="dialog-footer"><button class="outline" @click="step>1?step--:modal?.close()">{{step>1?'上一步':'取消'}}</button><span>第 {{step}} / 3 步</span><button class="primary" v-if="step<3" @click="advance">下一步 →</button><button class="primary" v-else @click="generate">生成报价草稿</button></div></template>
<template v-else-if="mode==='review'"><div class="dialog-body"><div class="detail-meta"><span class="badge" :class="selected.status==='已确认'?'green':'amber'">{{selected.status}}</span><h3>{{selected.customer}}</h3><p>{{selected.type}} · {{selected.brand}} · {{selected.date}}</p></div><p class="info">以产品为单位确认，该产品的所有数量档需一起核对。</p><article class="review-product" v-for="i in selected.count"><div class="section-heading"><div><h3>{{products[(i-1)%4]!.name}}</h3><p class="muted">{{products[(i-1)%4]!.spec}}</p></div><span class="badge green" v-if="confirmed.includes(i)||selected.status==='已确认'">已确认</span></div><div class="tier-summary"><span>订购数量</span><span>固定单价</span><span>货款</span></div><div class="tier-summary" v-for="t in [[500,'38.00','19,000.00'],[1000,'35.00','35,000.00']]"><b>{{t[0]}}</b><b>¥ {{t[1]}}</b><b>¥ {{t[2]}}</b></div><button class="outline full" v-if="selected.status==='待确认'&&!confirmed.includes(i)" @click="confirmProduct(i)">确认此产品的全部数量档</button></article></div><div class="dialog-footer"><button class="outline" @click="modal?.close()">关闭</button><button class="primary" v-if="selected.status==='草稿'" @click="submit">提交确认</button><span v-else class="muted">{{selected.status==='已确认'?'全部产品已确认':'已确认 '+confirmed.length+' / '+selected.count+' 款产品'}}</span></div></template>
<template v-else><div class="dialog-body" v-for="p in products.filter(p=>mode==='product:'+p.sku)"><span class="badge green">在售 · {{p.kind}}</span><h2>{{p.name}}</h2><p class="mono muted">{{p.sku}}</p><div class="summary-strip"><strong>规格</strong><span>{{p.spec}} / {{p.unit}}</span></div><h3>商品组成</h3><p>{{p.kind==='组合商品'?'简约保温杯 × 2，礼盒包装 × 1':'独立商品，无组成项。'}}</p></div></template>
</dialog><div class="toast" role="status" v-if="toast">✓ {{toast}}</div>
</template>
